/// <reference lib="webworker" />
import { precacheAndRoute } from 'workbox-precaching';
import { registerRoute } from 'workbox-routing';
import { CacheFirst, NetworkFirst, StaleWhileRevalidate } from 'workbox-strategies';
import { ExpirationPlugin } from 'workbox-expiration';
import { CacheableResponsePlugin } from 'workbox-cacheable-response';

declare const self: ServiceWorkerGlobalScope;

// Precache all assets generated by the build (fallback to empty array in dev mode)
precacheAndRoute(self.__WB_MANIFEST || []);

// Handle navigation requests - ALWAYS use network first for HTML pages
// This prevents the offline page from being cached
registerRoute(
    ({ request }) => request.mode === 'navigate',
    new NetworkFirst({
        cacheName: 'pages-cache',
        plugins: [
            new CacheableResponsePlugin({
                statuses: [0, 200],
            }),
        ],
        networkTimeoutSeconds: 3,
    })
);

// Cache Google Fonts
registerRoute(
    /^https:\/\/fonts\.googleapis\.com\/.*/i,
    new CacheFirst({
        cacheName: 'google-fonts-cache',
        plugins: [
            new ExpirationPlugin({
                maxEntries: 10,
                maxAgeSeconds: 60 * 60 * 24 * 365, // 1 year
            }),
            new CacheableResponsePlugin({
                statuses: [0, 200],
            }),
        ],
    })
);

// Cache Google Fonts static resources
registerRoute(
    /^https:\/\/fonts\.gstatic\.com\/.*/i,
    new CacheFirst({
        cacheName: 'gstatic-fonts-cache',
        plugins: [
            new ExpirationPlugin({
                maxEntries: 10,
                maxAgeSeconds: 60 * 60 * 24 * 365, // 1 year
            }),
            new CacheableResponsePlugin({
                statuses: [0, 200],
            }),
        ],
    })
);

// Cache Supabase API with NetworkFirst
registerRoute(
    /^https:\/\/.*\.supabase\.co\/rest\/v1\/.*/i,
    new NetworkFirst({
        cacheName: 'supabase-api-cache',
        plugins: [
            new ExpirationPlugin({
                maxEntries: 50,
                maxAgeSeconds: 60 * 5, // 5 minutes
            }),
            new CacheableResponsePlugin({
                statuses: [0, 200],
            }),
        ],
        networkTimeoutSeconds: 10,
    })
);

// Cache images (skip Mappls tile/map images)
registerRoute(
    ({ url, request }) =>
        /\.(?:png|jpg|jpeg|svg|gif|webp)$/i.test(url.pathname) &&
        !url.hostname.includes('mappls.com') &&
        !url.hostname.includes('mapmyindia.com'),
    new CacheFirst({
        cacheName: 'images-cache',
        plugins: [
            new ExpirationPlugin({
                maxEntries: 100,
                maxAgeSeconds: 60 * 60 * 24 * 30, // 30 days
            }),
        ],
    })
);

// Cache CSS files (skip Mappls SDK stylesheets)
registerRoute(
    ({ url }) =>
        /\.css$/i.test(url.pathname) &&
        !url.hostname.includes('mappls.com') &&
        !url.hostname.includes('mapmyindia.com'),
    new StaleWhileRevalidate({
        cacheName: 'css-cache',
        plugins: [
            new ExpirationPlugin({
                maxEntries: 20,
                maxAgeSeconds: 60 * 60 * 24 * 30, // 30 days
            }),
        ],
    })
);

// Cache JS files (skip Mappls SDK scripts)
registerRoute(
    ({ url }) =>
        /\.js$/i.test(url.pathname) &&
        !url.hostname.includes('mappls.com') &&
        !url.hostname.includes('mapmyindia.com'),
    new StaleWhileRevalidate({
        cacheName: 'js-cache',
        plugins: [
            new ExpirationPlugin({
                maxEntries: 30,
                maxAgeSeconds: 60 * 60 * 24 * 30, // 30 days
            }),
        ],
    })
);

// Offline fallback
self.addEventListener('fetch', (event) => {
    // Only handle navigation requests for HTML pages
    if (event.request.mode === 'navigate') {
        event.respondWith(
            fetch(event.request).catch((error) => {
                console.warn('[SW] Navigation failed, serving fallback:', error);
                // Return the precached /index.html if we're genuinely offline
                return caches.match('/index.html').then((response) => {
                    return response || caches.match('/offline.html');
                });
            })
        );
    }
});

// Background Sync - Sync pending mutations when connection is restored
self.addEventListener('sync', (event: any) => {
    console.log('🔄 Background sync event:', event.tag);

    if (event.tag === 'sync-mutations') {
        event.waitUntil(syncPendingMutations());
    }
});

// Periodic Background Sync - Sync data periodically (every 5 minutes)
self.addEventListener('periodicsync', (event: any) => {
    console.log('⏰ Periodic sync event:', event.tag);

    if (event.tag === 'periodic-sync') {
        event.waitUntil(periodicDataSync());
    }
});

// Helper function to sync pending mutations
async function syncPendingMutations() {
    try {
        console.log('📤 Syncing pending mutations...');

        // Send message to all clients to trigger sync
        const clients = await self.clients.matchAll();
        clients.forEach(client => {
            client.postMessage({
                type: 'SYNC_QUEUE',
                timestamp: Date.now()
            });
        });

        console.log('✅ Sync message sent to clients');
    } catch (error) {
        console.error('❌ Background sync failed:', error);
        throw error;
    }
}

// Helper function for periodic sync
async function periodicDataSync() {
    try {
        console.log('🔄 Periodic data sync...');

        // Send message to all clients to trigger periodic sync
        const clients = await self.clients.matchAll();
        clients.forEach(client => {
            client.postMessage({
                type: 'PERIODIC_SYNC',
                timestamp: Date.now()
            });
        });

        console.log('✅ Periodic sync message sent to clients');
    } catch (error) {
        console.error('❌ Periodic sync failed:', error);
    }
}

// Skip waiting and claim clients
self.addEventListener('install', (event) => {
    console.log('📦 Service worker installing...');
    self.skipWaiting();
});

self.addEventListener('activate', (event) => {
    console.log('✅ Service worker activated');
    event.waitUntil(self.clients.claim());
});

// Listen for messages from clients
self.addEventListener('message', (event) => {
    console.log('📨 Message received:', event.data);

    if (event.data?.type === 'SKIP_WAITING') {
        self.skipWaiting();
    }
});

// ═══════════════════════════════════════════════════════════════
// PUSH NOTIFICATIONS — Web Push API event handlers
// ═══════════════════════════════════════════════════════════════

/**
 * Push event — fired when a push message is received from the server.
 * This works even when the app is closed or in the background.
 */
self.addEventListener('push', (event) => {
    console.log('🔔 Push event received');

    if (!event.data) {
        console.warn('🔔 Push event has no data');
        return;
    }

    let payload: {
        title?: string;
        body?: string;
        icon?: string;
        badge?: string;
        tag?: string;
        data?: {
            url?: string;
            type?: string;
            order_id?: string;
            timestamp?: number;
        };
    };

    try {
        payload = event.data.json();
    } catch {
        // Fallback: treat as plain text
        payload = {
            title: 'Popclozet',
            body: event.data.text(),
        };
    }

    console.log('🔔 Push payload:', JSON.stringify(payload));

    const title = payload.title || 'Popclozet';
    const options = {
        body: payload.body || '',
        icon: payload.icon || '/icons/icon-192x192.png',
        badge: payload.badge || '/icons/icon-192x192.png',
        tag: payload.tag || 'general',
        renotify: true,
        requireInteraction: false,
        vibrate: [100, 50, 100, 50, 200],
        data: payload.data || {},
        actions: [
            { action: 'open', title: 'View' },
            { action: 'dismiss', title: 'Dismiss' },
        ],
    } as NotificationOptions & { renotify: boolean };

    event.waitUntil(
        self.registration.showNotification(title, options)
    );
});

/**
 * Notification click — opens the app to the relevant page.
 */
self.addEventListener('notificationclick', (event) => {
    console.log('🔔 Notification clicked:', event.notification.tag);

    event.notification.close();

    if (event.action === 'dismiss') {
        return;
    }

    // Get the target URL from the notification data
    const urlPath = event.notification.data?.url || '/';
    // Use HashRouter format since the app uses HashRouter
    const targetUrl = new URL(`/#${urlPath}`, self.location.origin).href;

    event.waitUntil(
        self.clients.matchAll({ type: 'window', includeUncontrolled: true }).then((clientList) => {
            // If an app window is already open, focus it and navigate
            for (const client of clientList) {
                if ('focus' in client) {
                    client.focus();
                    client.postMessage({
                        type: 'NOTIFICATION_CLICK',
                        url: urlPath,
                        data: event.notification.data,
                    });
                    return;
                }
            }
            // Otherwise, open a new window
            return self.clients.openWindow(targetUrl);
        })
    );
});

/**
 * Notification close — optional logging for analytics
 */
self.addEventListener('notificationclose', (event) => {
    console.log('🔔 Notification dismissed:', event.notification.tag);
});
